def run(state):
    code = state.get('code', '')
    functions = [f'func_at_line_{i}' for i, line in enumerate(code.splitlines(), start=1) if 'def ' in line]
    return {'functions': functions or ['main']}

def run(state):
    code = state.get('code', '')
    complexity = min(10, max(1, len(code) // 50))
    return {'complexity': complexity}

def run(state):
    issues_found = max(0, state.get('complexity', 1) - 3)
    return {'issues_found': issues_found}

def run(state):
    suggestions = []
    if state.get('complexity', 1) > 5:
        suggestions.append('Refactor large functions into smaller ones.')
    if state.get('issues_found', 0) > 0:
        suggestions.append('Reduce nested conditionals and loops.')
    if not suggestions:
        suggestions.append('Code looks clean. Minor style improvements only.')
    return {'suggestions': suggestions}
